<script setup lang="ts">
import { computed, defineAsyncComponent, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { api } from './api';
import type { ExportHistoryEntry, ExportResult, LogEntry, Part, Settings } from './types';
import GeometryViewport from './components/GeometryViewport.vue';
import Icon from './components/Icon.vue';
import UpdateDialog from './components/UpdateDialog.vue';
const ModelViewport=defineAsyncComponent(()=>import('./components/ModelViewport.vue'));
interface SessionTask {id:string;timestamp:string;target:string;partNames:string[];partCount:number;status:'running'|'success'|'error';directory:string;files:string[];warnings:string[];error?:string}
type FileEntry=Pick<SessionTask,'partNames'|'target'|'directory'|'files'|'warnings'|'error'>;
const parts=ref<Part[]>([]);const selectedID=ref('');const checked=ref<string[]>([]);const search=ref('');const searchInput=ref<HTMLTextAreaElement>();const queueFilter=ref('');const searchFocused=ref(false);const updatesOpen=ref(false);
const ready=ref(false);const fetching=ref(false);const importing=ref(false);const exporting=ref(false);const choosing=ref(false);const clearingQueue=ref(false);const clearingHistory=ref(false);const appVersion=ref('0.3.0');
const grid=ref(true);const showLabels=ref(true);const showSilk=ref(true);const showCopper=ref(true);const layersOpen=ref(false);const viewMenuOpen=ref(false);
const panel=ref<'help'|'settings'|'files'|null>(null);const fileEntry=ref<FileEntry>();const logs=ref<LogEntry[]>([]);const lastExport=ref<ExportResult>();const history=ref<ExportHistoryEntry[]>([]);const tasks=ref<SessionTask[]>([]);const taskTab=ref<'tasks'|'logs'>('tasks');
const toast=ref<{message:string;error:boolean}|null>(null);const fileInput=ref<HTMLInputElement>();const geometry=ref<{fit:()=>void}>();const modelView=ref<{fit:()=>void}>();
const defaults:Settings={outputDirectory:'',theme:'light',libraryName:'MyParts',includeSymbol:true,includeFootprint:true,includeModel:false,openAfterExport:false,exportTarget:'kicad',previewContent:'footprint',previewLayout:window.innerWidth>=1280?'split':'2d'};
const settings=reactive<Settings>({...defaults});
const target=computed({get:()=>settings.exportTarget,set:v=>settings.exportTarget=v});const contentMode=computed({get:()=>settings.previewContent,set:v=>settings.previewContent=v});const layout=computed({get:()=>settings.previewLayout,set:v=>settings.previewLayout=v});
const selected=computed(()=>parts.value.find(p=>p.id===selectedID.value));
const shownParts=computed(()=>{const q=queueFilter.value.trim().toLowerCase();return q?parts.value.filter(p=>[p.name,p.lcscId,p.package,p.description].some(s=>(s || '').toLowerCase().includes(q))):parts.value;});
const allChecked=computed(()=>parts.value.length>0 && checked.value.length===parts.value.length);const selectedParts=computed(()=>parts.value.filter(p=>checked.value.includes(p.id)));const latestLogs=computed(()=>logs.value.slice(-100));const lastLog=computed(()=>logs.value[logs.value.length-1]);
const completedTasks=computed(()=>tasks.value.filter(t=>t.status==='success').length);const failedTasks=computed(()=>tasks.value.filter(t=>t.status==='error').length);
const capabilities=ref<Record<string,boolean>>({kicad:true,altium:false,pads:false,cadence:false});
const targets=computed(()=>[{id:'altium',name:'AD',description:'SchLib / PcbLib',short:'AD',ready:!!capabilities.value.altium},{id:'pads',name:'PADS',description:'ASCII 导入包',short:'PA',ready:!!capabilities.value.pads},{id:'cadence',name:'Cadence',description:'EDA 脚本包',short:'Cd',ready:!!capabilities.value.cadence},{id:'kicad',name:'KiCad',description:'原生库文件',short:'Ki',ready:true}]);
const targetHint=computed(()=>target.value==='altium'?'直接生成独立 SchLib 与 PcbLib 库文件。':target.value==='pads'?'PADS ASCII 导入包：需要在 PADS 中导入，并由 PADS 保存原生库。':target.value==='cadence'?'Cadence 脚本包：需要在目标 EDA 中执行，才能生成原生库。':'生成 KiCad 原生文本库，可在目标版本中打开验证。');
const symbolFormat=computed(()=>target.value==='altium'?'.SchLib':target.value==='pads'?'原理图导入数据':target.value==='cadence'?'Capture Tcl 脚本':'.kicad_sym');
const footprintFormat=computed(()=>target.value==='altium'?'.PcbLib':target.value==='pads'?'PCB 导入数据':target.value==='cadence'?'Allegro 脚本':'.pretty / .kicad_mod');
let toastTimer:ReturnType<typeof setTimeout>;let logID=0;let saveTimer:ReturnType<typeof setTimeout>;let loadingSettings=false;
function log(message:string,level:LogEntry['level']='info'){logs.value.push({id:++logID,time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),message,level});if(logs.value.length>200)logs.value.shift();}
function notify(message:string,error=false){toast.value={message,error};clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value=null,5000);}
function errorMessage(e:unknown){return e instanceof Error?e.message:String(e);}
function targetLabel(value:string){return value==='altium'?'AD':value==='kicad'?'KiCad':value==='pads'?'PADS':value==='cadence'?'Cadence':value;}
function resizeSearch(){const input=searchInput.value;if(!input)return;input.style.height='34px';const height=searchFocused.value && search.value?Math.min(88,Math.max(34,input.scrollHeight)):34;input.style.height=`${height}px`;input.style.overflowY=height>=88?'auto':'hidden';}
watch(search,()=>{void nextTick(resizeSearch);});
function compactTarget(value:string){return value==='cadence'?'CDS':targetLabel(value);}
function completionText(value:string,count:number){return value==='cadence'?`Cadence 脚本包已生成，共 ${count} 个文件；需在目标 EDA 中执行。`:value==='pads'?`PADS ASCII 导入包已生成，共 ${count} 个文件；需在 PADS 中导入。`:`导出完成，共生成 ${count} 个文件。`;}
function generatedState(value:string){return value==='cadence'?'脚本包已生成':value==='pads'?'导入包已生成':'已完成';}
function timeLabel(value:string){const date=new Date(value);return Number.isNaN(date.valueOf())?value:date.toLocaleTimeString('zh-CN',{hour12:false,hour:'2-digit',minute:'2-digit'});}
function dateLabel(value:string){const date=new Date(value);return Number.isNaN(date.valueOf())?value:date.toLocaleString('zh-CN',{hour12:false});}
function fileName(value:string){return value.split(/[\\/]/).pop() || value;}
function normalizePart(part:Part):Part{return {...part,warnings:part.warnings || [],footprint:{...part.footprint,name:part.footprint?.name || part.package || part.name,pads:part.footprint?.pads || [],lines:part.footprint?.lines || [],circles:part.footprint?.circles || [],polygons:part.footprint?.polygons || [],texts:part.footprint?.texts || []},symbol:{...part.symbol,pins:part.symbol?.pins || [],lines:part.symbol?.lines || [],rects:part.symbol?.rects || []}};}
function mergePart(raw:Part){const p=normalizePart(raw);const i=parts.value.findIndex(v=>v.id===p.id);if(i>=0)parts.value[i]=p;else parts.value.push(p);if(!checked.value.includes(p.id))checked.value.push(p.id);selectedID.value=p.id;return p;}
async function initialize(){try{const boot=await api.bootstrap();loadingSettings=true;Object.assign(settings,defaults,boot.settings || {});if(!settings.libraryName)settings.libraryName='MyParts';if(!['footprint','symbol'].includes(settings.previewContent))settings.previewContent='footprint';if(!['2d','split','3d'].includes(settings.previewLayout))settings.previewLayout=defaults.previewLayout;Object.assign(capabilities.value,boot.capabilities || {});if(!capabilities.value[settings.exportTarget])settings.exportTarget='kicad';appVersion.value=boot.version || '0.3.0';parts.value=(boot.parts || []).map(normalizePart);checked.value=parts.value.map(p=>p.id);selectedID.value=parts.value[0]?.id || '';history.value=boot.history || [];ready.value=true;log(`工作台已就绪，已载入 ${parts.value.length} 个器件。`,'success');}catch(e){log(`初始化失败：${errorMessage(e)}`,'error');notify(`无法连接本地服务：${errorMessage(e)}`,true);}finally{loadingSettings=false;}}
async function fetchParts(){if(fetching.value || !search.value.trim())return;const ids=[...new Set((search.value.toUpperCase().match(/C\d+/g) || []))];if(!ids.length){notify('请输入立创 C 编号，例如 C23922。',true);return;}if(ids.length>50){notify('一次最多添加 50 个器件。',true);return;}fetching.value=true;let count=0;for(const id of ids){try{log(`正在获取 ${id}…`);const p=mergePart(await api.fetchPart(id));count++;log(`${id} · ${p.name} 已添加。`,'success');}catch(e){log(`${id} 获取失败：${errorMessage(e)}`,'error');notify(`${id}：${errorMessage(e)}`,true);}}fetching.value=false;if(count){search.value='';notify(`已添加 ${count} 个器件。`);}}
function searchKeydown(event:KeyboardEvent){if(event.isComposing)return;if(event.ctrlKey || event.metaKey){event.preventDefault();event.stopPropagation();const input=event.target as HTMLTextAreaElement;input.setRangeText('\n',input.selectionStart,input.selectionEnd,'end');search.value=input.value;}else if(!event.shiftKey){event.preventDefault();void fetchParts();}}
async function importJSON(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;importing.value=true;try{if(file.size>20*1024*1024)throw new Error('JSON 文件超过 20 MB。');const p=mergePart(await api.importPart(await file.text()));log(`已导入 ${file.name} · ${p.name}。`,'success');notify('器件已导入。');}catch(e){log(`导入失败：${errorMessage(e)}`,'error');notify(errorMessage(e),true);}finally{input.value='';importing.value=false;}}
function togglePart(id:string){checked.value=checked.value.includes(id)?checked.value.filter(v=>v!==id):[...checked.value,id];}function toggleAll(){checked.value=allChecked.value?[]:parts.value.map(p=>p.id);}
async function removePart(id:string){try{await api.removePart(id);parts.value=parts.value.filter(p=>p.id!==id);checked.value=checked.value.filter(v=>v!==id);if(selectedID.value===id)selectedID.value=parts.value[0]?.id || '';}catch(e){notify(errorMessage(e),true);}}
async function clearQueue(){if(fetching.value || exporting.value || clearingQueue.value)return;clearingQueue.value=true;for(const p of [...parts.value])await removePart(p.id);clearingQueue.value=false;}
async function chooseDirectory(){choosing.value=true;try{const path=await api.chooseDirectory();if(path)settings.outputDirectory=path;}catch(e){notify(`${errorMessage(e)}；也可直接填写路径。`,true);}finally{choosing.value=false;}}
async function openDirectory(path?:string){const directory=path || settings.outputDirectory;if(!directory){notify('请先填写导出目录。',true);return;}try{await api.openDirectory(directory);}catch(e){notify(errorMessage(e),true);}}
async function revealFile(path:string){try{await api.revealFile(path);}catch(e){notify(errorMessage(e),true);}}
async function refreshHistory(){try{history.value=await api.history();}catch(e){log(`历史记录读取失败：${errorMessage(e)}`,'warn');}}
async function clearHistory(){if(clearingHistory.value)return;clearingHistory.value=true;try{await api.clearHistory();history.value=[];notify('已清空导出历史，生成的文件保留。');}catch(e){notify(errorMessage(e),true);}finally{clearingHistory.value=false;}}
function showFiles(entry:FileEntry){fileEntry.value=entry;panel.value='files';}
async function runExport(){if(exporting.value || panel.value)return;if(!checked.value.length){notify('请勾选要导出的器件。',true);return;}if(!settings.includeSymbol && !settings.includeFootprint){notify('请至少选择一种导出内容。',true);return;}if(!settings.outputDirectory.trim()){notify('请先选择或填写输出目录。',true);return;}if(!settings.libraryName.trim()){notify('请填写库名称。',true);return;}const chosen=selectedParts.value;const chosenTarget=target.value;const task:SessionTask={id:`task-${Date.now()}`,timestamp:new Date().toISOString(),target:chosenTarget,partNames:chosen.map(p=>p.name),partCount:chosen.length,status:'running',directory:settings.outputDirectory,files:[],warnings:[]};tasks.value.unshift(task);taskTab.value='tasks';exporting.value=true;log(`开始导出 ${chosen.length} 个器件到 ${targetLabel(chosenTarget)}…`);const taskID=task.id;const update=(values:Partial<SessionTask>)=>{const current=tasks.value.find(t=>t.id===taskID);if(current)Object.assign(current,values);};try{const result=await api.exportParts({partIds:chosen.map(p=>p.id),outputDirectory:settings.outputDirectory,libraryName:settings.libraryName,includeSymbol:settings.includeSymbol,includeFootprint:settings.includeFootprint,includeModel:settings.includeModel,target:chosenTarget});lastExport.value=result;update({status:'success',directory:result.directory,files:result.files || [],warnings:result.warnings || []});log(completionText(chosenTarget,result.files.length),'success');for(const warning of result.warnings || [])log(warning,'warn');notify(completionText(chosenTarget,result.files.length));if(settings.openAfterExport)await openDirectory(result.directory);}catch(e){const message=errorMessage(e);update({status:'error',error:message});log(`导出失败：${message}`,'error');notify(message,true);}finally{exporting.value=false;await refreshHistory();}}
function resetDefaults(){Object.assign(settings,defaults,{theme:settings.theme,outputDirectory:settings.outputDirectory,libraryName:settings.libraryName});grid.value=true;showLabels.value=true;showSilk.value=true;showCopper.value=true;notify('已恢复默认选项，保留输出目录与库名。');}
function resetViews(){geometry.value?.fit();modelView.value?.fit();}function toggleTheme(){settings.theme=settings.theme==='light'?'dark':'light';}
watch(()=>settings.theme,v=>document.documentElement.dataset.theme=v,{immediate:true});watch(settings,()=>{if(loadingSettings || !ready.value)return;clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{await api.saveSettings({...settings});}catch(e){log(`设置保存失败：${errorMessage(e)}`,'warn');}},500);},{deep:true});
function keyboard(e:KeyboardEvent){if(e.isComposing)return;if((e.ctrlKey || e.metaKey) && e.key.toLowerCase()==='k'){e.preventDefault();searchInput.value?.focus();return;}const element=e.target as HTMLElement|null;const editing=!!element?.closest('input,textarea,select,[contenteditable="true"]');if((e.ctrlKey || e.metaKey) && e.shiftKey && e.key==='Enter' && !editing && !panel.value && !updatesOpen.value){e.preventDefault();void runExport();}if(e.key==='Escape'){if(panel.value)panel.value=null;else{layersOpen.value=false;viewMenuOpen.value=false;}}}
onMounted(()=>{void initialize();window.addEventListener('keydown',keyboard);});onBeforeUnmount(()=>{window.removeEventListener('keydown',keyboard);clearTimeout(toastTimer);clearTimeout(saveTimer);});
</script>

<template>
 <div class="studio-shell">
  <header class="topbar"><div class="top-menus"><div class="menu-anchor"><button class="menu-button" :class="{active:viewMenuOpen}" @click="viewMenuOpen=!viewMenuOpen"><Icon name="grid" :size="16"/>视图<Icon name="down" :size="12"/></button><div v-if="viewMenuOpen" class="view-menu"><strong>预览布局</strong><div class="segmented"><button :class="{active:layout==='2d'}" @click="layout='2d'">2D</button><button :class="{active:layout==='split'}" @click="layout='split'">并排</button><button :class="{active:layout==='3d'}" @click="layout='3d'">3D</button></div><label class="checkbox-label"><input type="checkbox" v-model="grid"><span>显示网格</span></label><label class="checkbox-label"><input type="checkbox" v-model="showLabels"><span>显示引脚编号与文字</span></label><button class="text-button" @click="resetViews();viewMenuOpen=false"><Icon name="fit" :size="15"/>复位预览视图</button></div></div><button class="menu-button" @click="panel='settings'"><Icon name="settings" :size="16"/>设置</button><button class="menu-button" @click="panel='help'"><Icon name="help" :size="16"/>帮助</button><button class="menu-button" @click="updatesOpen=true"><Icon name="refresh" :size="16"/>检查更新</button></div><div class="top-brand"><Icon name="chip" :size="19"/><strong>封装工坊</strong><span>v{{appVersion}}</span></div><button class="theme-button" @click="toggleTheme" :title="settings.theme==='light'?'切换深色主题':'切换浅色主题'"><Icon :name="settings.theme==='light'?'moon':'sun'" :size="16"/><span>{{settings.theme==='light'?'深色':'浅色'}}</span></button></header>
  <div class="workspace">
   <aside class="left-column">
    <section class="queue-panel pane"><header class="pane-heading"><h2><Icon name="cube" :size="19"/>封装列表 <span>（{{parts.length}}）</span></h2><button class="primary-button compact" @click="fileInput?.click()" :disabled="importing"><Icon name="plus" :size="16"/>{{importing?'导入中':'添加文件'}}</button></header><div class="search-wrap"><textarea ref="searchInput" v-model="search" rows="1" placeholder="输入 C 编号，Enter 获取" title="Enter 获取，Ctrl+Enter 换行；可输入多个 C 编号" @focus="searchFocused=true;resizeSearch()" @blur="searchFocused=false;resizeSearch()" @input="resizeSearch" aria-label="输入立创 C 编号" :disabled="fetching" @keydown.enter="searchKeydown"></textarea><button class="search-submit" :disabled="fetching || !search.trim()" @click="fetchParts" title="获取器件" aria-label="获取器件"><span v-if="fetching" class="spinner"></span><Icon v-else name="search" :size="20"/></button></div><div class="queue-tools"><label class="checkbox-label"><input type="checkbox" :checked="allChecked" @change="toggleAll"><span>全选 <b>{{checked.length}}</b></span></label><div v-if="parts.length>5" class="queue-filter"><input v-model="queueFilter" placeholder="筛选列表" aria-label="筛选器件队列"><Icon name="search" :size="13"/></div><span v-else>支持批量 C 编号</span></div><div class="parts-list"><article v-for="p in shownParts" :key="p.id" class="part-card" :class="{active:selectedID===p.id}" tabindex="0" role="button" @click="selectedID=p.id" @keydown.enter="selectedID=p.id"><div class="part-card-row"><span class="part-check" :class="{checked:checked.includes(p.id)}" role="checkbox" :aria-checked="checked.includes(p.id)" tabindex="0" @click.stop="togglePart(p.id)" @keydown.space.prevent.stop="togglePart(p.id)"><Icon v-if="checked.includes(p.id)" name="check" :size="12" :stroke="2.6"/></span><strong :title="p.name">{{p.name}}</strong><button class="part-remove icon-button" title="从列表移除" aria-label="从列表移除此器件" @click.stop="removePart(p.id)"><Icon name="close" :size="14"/></button></div><div class="part-card-meta"><span class="mono">{{p.lcscId || '本地器件'}}</span><span class="meta-separator">·</span><span :title="p.package">{{p.package || p.footprint.name || '自定义封装'}}</span><span v-if="/example|demo|示例/i.test(p.source)" class="sample-tag">示例</span></div><p :title="p.description">{{p.description || p.manufacturer || p.source}}</p></article><div v-if="!parts.length" class="queue-empty"><Icon name="chip" :size="40" :stroke="1.2"/><strong>{{ready?'列表中还没有器件':'正在连接工作台'}}</strong><p>输入 C 编号，或添加 EasyEDA JSON 文件。</p><button v-if="!ready" class="secondary-button" @click="initialize"><Icon name="refresh" :size="14"/>重新连接</button></div></div><footer class="queue-footer"><button class="text-button" :disabled="!parts.length || exporting || fetching || clearingQueue" @click="clearQueue"><Icon name="trash" :size="15"/>{{clearingQueue?'清理中…':'清空列表'}}</button><span>{{fetching?'正在获取器件…':`已添加 ${parts.length} 个器件`}}</span></footer></section>
    <section class="history-panel pane"><header class="pane-heading"><h2><Icon name="clock" :size="19"/>导出历史记录</h2><button class="text-button" :disabled="!history.length || clearingHistory" @click="clearHistory"><Icon name="trash" :size="14"/>清空</button></header><div class="history-table-wrap"><table class="history-table"><thead><tr><th>时间</th><th>器件</th><th>格式</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="entry in history" :key="entry.id"><td class="mono" :title="dateLabel(entry.timestamp)">{{timeLabel(entry.timestamp)}}</td><td class="history-name" :title="entry.partNames.join('、')">{{entry.partNames[0] || '导出任务'}}<span v-if="entry.partCount>1"> 等 {{entry.partCount}} 个</span></td><td :title="targetLabel(entry.target)">{{compactTarget(entry.target)}}</td><td><span class="small-state" :class="entry.status">{{entry.status==='success'?(entry.target==='pads' || entry.target==='cadence'?'生成':'完成'):'失败'}}</span></td><td><button class="icon-button" :disabled="!entry.files.length && !entry.error" title="查看本次导出结果" aria-label="查看导出结果" @click="showFiles(entry)"><Icon :name="entry.status==='success'?'folder':'info'" :size="15"/></button></td></tr></tbody></table><div v-if="!history.length" class="history-empty"><Icon name="file" :size="39" :stroke="1.2"/><span>暂无导出记录</span><p>完成导出后，结果会保存在这里。</p></div></div></section>
   </aside>
   <main class="center-column">
    <section class="preview-panel pane"><header class="preview-heading"><div><h1>预览：<span>{{selected?.name || '请选择器件'}}</span></h1><p v-if="selected"><span>{{selected.package || '自定义封装'}}</span><i></i><span>{{selected.footprint.pads.length}} 个焊盘</span><i></i><span>{{selected.lcscId || '本地导入'}}</span></p><p v-else>添加器件后，可以核对原理图、封装和实际模型。</p></div><button class="icon-button" title="复位所有预览视图" aria-label="复位预览视图" @click="resetViews"><Icon name="fit" :size="18"/></button></header><div class="preview-toolbar"><div class="toolbar-group"><span>内容</span><div class="segmented" role="tablist" aria-label="预览内容"><button :class="{active:contentMode==='symbol'}" role="tab" :aria-selected="contentMode==='symbol'" @click="contentMode='symbol'">原理图符号</button><button :class="{active:contentMode==='footprint'}" role="tab" :aria-selected="contentMode==='footprint'" @click="contentMode='footprint'">2D 封装</button></div></div><div class="toolbar-group layout-group"><span>布局</span><div class="segmented" role="tablist" aria-label="预览布局"><button :class="{active:layout==='2d'}" @click="layout='2d'">2D</button><button :class="{active:layout==='split'}" @click="layout='split'">并排</button><button :class="{active:layout==='3d'}" @click="layout='3d'">3D</button></div></div><div class="layers-menu"><button class="icon-button" title="显示图层与网格" aria-label="显示图层与网格" :class="{active:layersOpen}" @click="layersOpen=!layersOpen"><Icon name="layers" :size="18"/></button><div v-if="layersOpen" class="layers-dropdown"><label class="checkbox-label"><input type="checkbox" v-model="grid"><span>网格</span></label><label class="checkbox-label"><input type="checkbox" v-model="showCopper"><span><i class="layer-color copper"></i>铜层与焊盘</span></label><label class="checkbox-label"><input type="checkbox" v-model="showSilk"><span><i class="layer-color silk"></i>丝印与轮廓</span></label><label class="checkbox-label"><input type="checkbox" v-model="showLabels"><span>引脚编号与文字</span></label></div></div></div><div class="preview-content" :class="`layout-${layout}`"><template v-if="selected"><div v-if="layout!=='3d'" class="preview-cell geometry-cell"><div class="preview-cell-heading"><span><Icon :name="contentMode==='footprint'?'chip':'activity'" :size="14"/>{{contentMode==='footprint'?'PCB 封装':'原理图符号'}}</span><span v-if="contentMode==='symbol'">{{selected.symbol.units || 1}} 个单元</span><span v-else class="mono">mm</span></div><div class="cell-viewport"><GeometryViewport ref="geometry" :part="selected" :mode="contentMode" :grid="grid" :show-labels="showLabels" :show-silk="showSilk" :show-copper="showCopper"/><div class="drawing-legend"><span><i class="layer-color copper"></i>{{contentMode==='footprint'?'焊盘':'引脚'}}</span><span><i class="layer-color silk"></i>{{contentMode==='footprint'?'丝印':'符号轮廓'}}</span><span class="mono">{{contentMode==='footprint'?selected.footprint.pads.length:selected.symbol.pins.length}} {{contentMode==='footprint'?'PADS':'PINS'}}</span></div></div></div><div v-if="layout!=='2d'" class="preview-cell model-cell"><div class="preview-cell-heading"><span><Icon name="cube" :size="14"/>3D 模型</span><span>按需载入</span></div><div class="cell-viewport"><ModelViewport ref="modelView" :key="selected.id" :part="selected" :dark="settings.theme==='dark'"/></div></div></template><div v-else class="preview-empty"><Icon name="chip" :size="55" :stroke="1.1"/><h2>先添加一个器件</h2><p>输入 C 编号或导入 JSON，即可查看实际几何数据。</p><button class="primary-button" @click="searchInput?.focus()"><Icon name="plus" :size="16"/>添加器件</button></div></div><div class="preview-note"><Icon name="info" :size="14"/><span>焊盘、引脚对应关系和外形尺寸，请以器件资料核对。</span><span v-if="selected" class="source-label" :title="selected.source">{{/example|demo|示例/i.test(selected.source)?'独立绘制示例':'源数据预览'}}</span></div></section>
    <section class="task-panel pane"><header class="task-heading"><div class="task-tabs"><button :class="{active:taskTab==='tasks'}" @click="taskTab='tasks'">导出任务 <span>（{{tasks.length}}）</span></button><button :class="{active:taskTab==='logs'}" @click="taskTab='logs'">运行日志</button></div><div class="task-counts"><span class="success"><Icon name="check" :size="13"/>完成 {{completedTasks}}</span><span v-if="failedTasks" class="error"><Icon name="close" :size="13"/>失败 {{failedTasks}}</span><button class="text-button" :disabled="exporting || !tasks.length" @click="tasks=[]"><Icon name="trash" :size="14"/>清空</button></div></header><div v-if="taskTab==='tasks'" class="task-table-wrap"><table class="task-table"><thead><tr><th>器件 / 批次</th><th>目标</th><th>状态</th><th>生成文件</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id"><td><strong :title="task.partNames.join('、')">{{task.partNames[0]}}<span v-if="task.partCount>1"> 等 {{task.partCount}} 个器件</span></strong><small :title="task.error || task.directory">{{task.error || task.directory}}</small></td><td>{{targetLabel(task.target)}}</td><td><span class="task-state" :class="task.status"><span v-if="task.status==='running'" class="spinner tiny"></span><Icon v-else :name="task.status==='success'?'check':'close'" :size="13"/>{{task.status==='running'?'正在生成':task.status==='success'?generatedState(task.target):'失败'}}</span></td><td><button v-if="task.status!=='running'" class="text-button" @click="showFiles(task)"><Icon :name="task.files.length?'folder':'info'" :size="15"/>{{task.files.length?`${task.files.length} 个文件`:'查看详情'}}</button><span v-else class="muted">等待结果</span><button v-if="task.warnings.length" class="task-warning-link" :title="task.warnings.join('；')" @click="showFiles(task)"><Icon name="warning" :size="12"/>{{task.warnings.length}} 条提示</button></td></tr></tbody></table><div v-if="!tasks.length" class="task-empty"><Icon name="list" :size="27" :stroke="1.2"/><span>勾选器件并开始导出后，这里显示本次任务状态。</span></div></div><div v-else class="activity-logs"><div v-for="entry in latestLogs" :key="entry.id" class="log-line" :class="entry.level"><span class="mono">{{entry.time}}</span><Icon :name="entry.level==='success'?'check':entry.level==='error'?'close':entry.level==='warn'?'warning':'chevron'" :size="13"/><span>{{entry.message}}</span></div></div></section>
   </main>
   <aside class="export-panel pane"><header class="pane-heading"><h2>导出设置</h2><button class="text-button" @click="resetDefaults"><Icon name="refresh" :size="14"/>恢复默认</button></header><div class="export-scroll"><section class="export-group"><h3>1. 目标软件</h3><div class="target-grid"><button v-for="t in targets" :key="t.id" class="target-card" :class="{active:target===t.id,unavailable:!t.ready}" :disabled="!t.ready" :title="t.ready?t.description:'该适配器尚未实现'" @click="target=t.id"><strong>{{t.name}}</strong><small>{{t.ready?t.description:'规划中'}}</small><Icon v-if="target===t.id" name="check" :size="15"/></button></div><p class="field-hint">{{targetHint}}</p></section><section class="export-group"><h3>2. 导出内容</h3><div class="content-options"><label class="checkbox-label"><input type="checkbox" v-model="settings.includeSymbol"><span>原理图符号</span></label><label class="checkbox-label"><input type="checkbox" v-model="settings.includeFootprint"><span>PCB 封装</span></label></div><div class="format-note"><span>{{settings.includeSymbol?symbolFormat:''}}</span><span>{{settings.includeFootprint?footprintFormat:''}}</span></div></section><section class="export-group"><h3>3. 默认输出位置</h3><label class="radio-label"><input type="radio" checked name="output-mode"><span>导出到指定文件夹</span></label><label class="radio-label disabled" title="当前版本尚未支持已有库合并"><input type="radio" disabled name="output-mode"><span>添加到已有库 <small>尚未支持</small></span></label><label class="field-label output-label" for="output-dir">输出目录 <button class="text-button" @click="openDirectory()">打开<Icon name="export" :size="12"/></button></label><div class="directory-input"><input id="output-dir" v-model="settings.outputDirectory" placeholder="选择或输入输出目录" :title="settings.outputDirectory"><button :disabled="choosing" @click="chooseDirectory" title="选择输出目录" aria-label="选择输出目录"><span v-if="choosing" class="spinner tiny"></span><Icon v-else name="folder" :size="18"/></button></div><label class="field-label library-label" for="library-name">库名称</label><input id="library-name" class="text-input mono" v-model="settings.libraryName" placeholder="MyParts" maxlength="80"><p class="field-hint">所选器件整理到同一库中；已有文件的处理结果会显示在日志里。</p></section><section class="export-group"><h3>4. 其他选项</h3><label class="checkbox-label option-row"><input type="checkbox" v-model="settings.includeModel"><span>下载 STEP 模型（如有）</span></label><label class="checkbox-label option-row"><input type="checkbox" v-model="settings.openAfterExport"><span>导出完成后打开所在目录</span></label><p class="field-hint">模型按需联网获取。几何解析与库文件生成在本地完成。</p></section><section v-if="selected?.warnings.length" class="part-warnings"><h4><Icon name="warning" :size="15"/>当前器件提示</h4><p v-for="(w,i) in selected.warnings" :key="i">{{w}}</p></section></div><footer class="export-footer"><div class="export-selection"><span>已选择 {{selectedParts.length}} 个器件</span><span>{{targetLabel(target)}}</span></div><button class="primary-button export-button" :disabled="exporting || !checked.length || !ready" @click="runExport"><span v-if="exporting" class="spinner"></span><Icon v-else name="export" :size="20"/>{{exporting?'正在导出…':`开始导出（${selectedParts.length}）`}}</button><div class="export-shortcut">Ctrl + Shift + Enter <span>开始导出</span></div></footer></aside>
  </div>
  <footer class="statusbar"><div><span class="status-dot" :class="{'not-ready':!ready}"></span>{{ready?'工作台已就绪':'本地服务未连接'}}<span class="status-separator"></span><span>{{lastLog?.level==='error'?'任务出现异常，请查看运行日志':exporting?'正在生成库文件，请等待实际结果。':'本地处理 · 几何单位 mm'}}</span></div><button v-if="lastExport" class="text-button" @click="openDirectory(lastExport.directory)"><Icon name="folder" :size="13"/>打开最近结果</button></footer>
  <UpdateDialog v-if="updatesOpen" :current-version="appVersion" @close="updatesOpen=false"/><input ref="fileInput" type="file" accept=".json,application/json" hidden @change="importJSON">
  <Transition name="toast"><div v-if="toast" class="toast-message" :class="{error:toast.error}" role="status"><Icon :name="toast.error?'warning':'check'" :size="18"/><span>{{toast.message}}</span><button aria-label="关闭提示" @click="toast=null"><Icon name="close" :size="15"/></button></div></Transition>
  <div v-if="panel" class="modal-overlay" @click.self="panel=null"><section class="modal" :class="{'files-modal':panel==='files'}" role="dialog" aria-modal="true" :aria-label="panel==='help'?'使用帮助':panel==='settings'?'工作台设置':'导出结果'"><header><h2>{{panel==='help'?'使用帮助':panel==='settings'?'工作台设置':'实际导出结果'}}</h2><button class="icon-button" aria-label="关闭弹窗" @click="panel=null"><Icon name="close"/></button></header><div v-if="panel==='help'" class="help-body"><div class="help-step"><b>1</b><div><h3>添加与选择器件</h3><p>输入立创 C 编号后按 Enter 获取。Ctrl+Enter 换行，可一次输入多个编号。也可以点击“添加文件”导入 EasyEDA 标准版 JSON。</p></div></div><div class="help-step"><b>2</b><div><h3>核对 2D 与 3D</h3><p>“内容”切换原理图与封装，“布局”切换 2D、并排和 3D。拖动平移、滚轮缩放；实际模型需点击载入，几何示意会单独标注。</p></div></div><div class="help-step"><b>3</b><div><h3>导出后回读验证</h3><p>选择目标软件和输出位置后开始导出。Ctrl+Shift+Enter 可在非输入状态触发导出。历史与任务区只显示真实返回的文件和状态。</p></div></div><div class="modal-note"><Icon name="info" :size="17"/><p>{{capabilities.altium?'当前支持 KiCad 和 AD 原生库导出。':'当前支持 KiCad 原生库导出。'}}PADS 输出 ASCII 导入包；Cadence 输出脚本包，需目标 EDA 生成原生库。已有库合并和自动全局库注册尚未提供。请在目标软件中核对焊盘、引脚和图层。</p></div></div><div v-else-if="panel==='settings'" class="settings-body"><label class="field-label">外观主题</label><div class="theme-choices"><button class="theme-choice" :class="{active:settings.theme==='light'}" @click="settings.theme='light'"><Icon name="sun" :size="22"/><strong>浅色主题</strong></button><button class="theme-choice" :class="{active:settings.theme==='dark'}" @click="settings.theme='dark'"><Icon name="moon" :size="22"/><strong>深色主题</strong></button></div><label class="field-label">默认预览布局</label><div class="segmented settings-layout"><button :class="{active:layout==='2d'}" @click="layout='2d'">2D</button><button :class="{active:layout==='split'}" @click="layout='split'">2D 与 3D 并排</button><button :class="{active:layout==='3d'}" @click="layout='3d'">3D</button></div><p class="field-hint">主题、输出设置与预览布局会自动保存在本地。</p><div class="modal-note"><Icon name="connection" :size="17"/><p>联网用于获取选定器件及模型；导出历史保存在本地。清空历史不会删除生成的文件。</p></div></div><div v-else-if="fileEntry" class="files-body"><div class="result-summary"><strong>{{fileEntry.partNames.join('、')}}</strong><span>{{targetLabel(fileEntry.target)}} · {{fileEntry.files.length}} 个实际文件</span></div><div v-if="fileEntry.target==='cadence' || fileEntry.target==='pads'" class="modal-note artifact-stage"><Icon name="info" :size="17"/><p>{{fileEntry.target==='cadence'?'目标产物为 Cadence 脚本包，需在目标 EDA 中执行生成原生库。此记录不代表原生库已生成。':'目标产物为 PADS ASCII 导入包，需在 PADS 中导入后保存并验证原生库。'}}</p></div><p v-if="fileEntry.error" class="result-error">{{fileEntry.error}}</p><div class="result-directory"><Icon name="folder" :size="16"/><span class="mono">{{fileEntry.directory || '未生成结果目录'}}</span><button v-if="fileEntry.directory" class="text-button" @click="openDirectory(fileEntry.directory)">打开目录</button></div><ul class="generated-files"><li v-for="file in fileEntry.files" :key="file"><Icon name="file" :size="16"/><button class="generated-file-name mono" :title="file" @click="revealFile(file)">{{fileName(file)}}</button><button class="icon-button" title="在文件夹中定位" aria-label="在文件夹中定位文件" @click="revealFile(file)"><Icon name="folder" :size="16"/></button></li></ul><p v-if="!fileEntry.files.length" class="field-hint">此记录没有返回可定位的生成文件。</p><div v-if="fileEntry.warnings?.length" class="part-warnings"><h4>导出提示</h4><p v-for="(warning,i) in fileEntry.warnings" :key="i">{{warning}}</p></div></div><footer><span>按 Esc 关闭</span><button class="primary-button compact" @click="panel=null">完成</button></footer></section></div>
 </div>
</template>





